/// Bead `sts2-rs-fkwls`: file-local block grant that bypasses
/// Frail/Dexterity modifiers — mirrors C# `BlockVar(N, ValueProp.Unpowered)`
/// on listener-driven relic block grants. Identical control flow to
/// [`crate::card_effects::gain_block_player`] except the `ValueProps`
/// flag set carries `UNPOWERED` so `modify_block` listeners that gate on
/// `is_powered()` (Frail / Dexterity / Inflame-mirror) skip the grant.
pub(crate) fn gain_block_player_unpowered(state: &mut CombatState, base: i32) {
    let ctx = BlockCtx {
        target: CreatureRef::Player,
        props: ValueProps::MOVE.union(ValueProps::UNPOWERED),
        card_source: None,
    };
    let final_block = hooks::modify_block(state, base, &ctx);
    state.player.block = state.player.block.saturating_add(final_block);
    state.sync_creature_block_from_player();
    if final_block > 0 {
        let gained_ctx = BlockGainedCtx {
            target: CreatureRef::Player,
            amount: final_block,
            card_source: None,
        };
        hooks::dispatch_after_block_gained(state, &gained_ctx);
        let _ = crate::relic_effects::dispatch_after_block_gained(state, &gained_ctx);
    }
}

